/* GLITZ PERFUMARIA LUXURY SYSTEM */
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,600;1,400&family=Plus+Jakarta+Sans:wght@300;400;500;600;700&display=swap');

:root {
  --glitz-emerald: #1D3D40;
  --glitz-forest: #294F52;
  --glitz-dark: #0D1C1E;
  --glitz-gold: #C5A880;
  --glitz-gold-light: #DFCEB8;
  --glitz-bg-warm: #F8F7F3;
  --glitz-text: #182324;
}

body {
  font-family: 'Plus Jakarta Sans', sans-serif !important;
  color: #182324 !important;
}

h1, h2, h3, .h1, .h2, .h3 {
  letter-spacing: -0.5px !important;
}

/* Luxury Promo Bar */
.section-navigation-bar, .navigation-bar, header .announcement-bar {
  background-color: #294F52 !important;
  color: #FFFFFF !important;
  font-size: 11px !important;
  letter-spacing: 2px !important;
  text-transform: uppercase !important;
  font-weight: 600 !important;
}

/* Gold & Emerald Buttons */
.btn-gold, .btn-primary, button.btn-primary, a.btn-primary, .button-primary {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  background: linear-gradient(135deg, #1D3D40 0%, #122628 100%) !important;
  color: #FFFFFF !important;
  font-weight: 700 !important;
  letter-spacing: 1.5px !important;
  text-transform: uppercase !important;
  border-radius: 6px !important;
  border: 1px solid rgba(197, 168, 128, 0.3) !important;
  box-shadow: 0 4px 14px rgba(29, 61, 64, 0.25) !important;
  transition: all 0.3s ease !important;
}

.btn-primary:hover, button.btn-primary:hover, a.btn-primary:hover, .button-primary:hover {
  background: linear-gradient(135deg, #2D585C 0%, #1D3D40 100%) !important;
  box-shadow: 0 6px 20px rgba(29, 61, 64, 0.35) !important;
  transform: translateY(-2px) !important;
}

.btn-secondary, button.btn-secondary, a.btn-secondary, .button-secondary {
  border: 1.5px solid #1D3D40 !important;
  color: #1D3D40 !important;
  border-radius: 6px !important;
  font-weight: 700 !important;
  letter-spacing: 1.5px !important;
  text-transform: uppercase !important;
  transition: all 0.3s ease !important;
}

.btn-secondary:hover, button.btn-secondary:hover, a.btn-secondary:hover, .button-secondary:hover {
  background: #1D3D40 !important;
  color: #FFFFFF !important;
}

/* Product Card Refinements */
.item-product, .product-item, .card-product, .product-card {
  border-radius: 12px !important;
  overflow: hidden !important;
  background: #FFFFFF !important;
  border: 1px solid #E8ECEB !important;
  transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.4s cubic-bezier(0.16, 1, 0.3, 1) !important;
}

.item-product:hover, .product-item:hover, .card-product:hover, .product-card:hover {
  transform: translateY(-6px) !important;
  box-shadow: 0 16px 36px -10px rgba(29, 61, 64, 0.15) !important;
  border-color: #DFCEB8 !important;
}

.item-image img, .product-item-image img, .product-card img {
  transition: transform 0.7s cubic-bezier(0.16, 1, 0.3, 1) !important;
}

.item-product:hover .item-image img, .product-item:hover img, .product-card:hover img {
  transform: scale(1.08) !important;
}

/* Footer Luxury */
footer, .section-footer {
  background-color: #1D3D40 !important;
  color: #FFFFFF !important;
}

footer a, .section-footer a {
  color: #BFC5C3 !important;
  transition: color 0.2s ease !important;
}

footer a:hover, .section-footer a:hover {
  color: #FFFFFF !important;
}
